import type { QuizAnswers } from "@open-mtlms/shared";

import type { ApiResponse, Tenant } from "../types/auth";

import { apiClient } from "./axios";

/**
 * Provisioned-academy fields returned by the backend when quiz_answers are
 * supplied. The backend creates the tenant SHELL only (tenant + plan +
 * intent profile + subdomain). Pages are created + AI-generated by the
 * frontend after this returns, mirroring the existing /dashboard/pages
 * onboarding wizard. Bare creates omit these, pure additive shape.
 */
export interface ProvisionedAcademy extends Tenant {
  subdomainUrl?: string;
  template_id?: string;
  theme_id?: string;
  generation_source?: "ai" | "fallback";
  /** Quiz answers echoed back so the frontend can synthesize BusinessInfo for AI. */
  quiz_answers?: QuizAnswers;
}

export interface CreateOrganizationPayload {
  name: string;
  /**
   * When present, the backend runs the auto-provisioning flow:
   * picks template/theme via Gemini, creates tenant + auto-assigns latest
   * FREE plan + persists creator_intent_profile + registers subdomain.
   * Frontend then runs per-section AI generation (same engine as the
   * pre-update wizard) for every page.
   */
  quiz_answers?: QuizAnswers;
  timezone?: string;
}

/**
 * Organization API service
 */
export const organizationApi = {
  /**
   * Create a new organization for the authenticated user
   */
  createOrganization: async (
    data: CreateOrganizationPayload,
  ): Promise<ProvisionedAcademy> => {
    const response = await apiClient.post<ApiResponse<ProvisionedAcademy>>(
      "/tenant/organization",
      data
    );
    return response.data.data;
  },

  /**
   * Update organization name (owner only)
   */
  updateName: async (
    name: string
  ): Promise<{ id: string; name: string; slug: string }> => {
    const response = await apiClient.patch<
      ApiResponse<{ id: string; name: string; slug: string }>
    >("/tenant/organization/name", { name });
    return response.data.data;
  },
};
